//go:generate protoc -I ../../../../web/proto --go_out=. --go_opt=paths=source_relative ../../../../web/proto/web.proto
//go:generate sh -c "printf '// Code generated by go generate; DO NOT EDIT.\n\npackage rpc\n\nconst protoSHA256 = \"%s\"\n' $(shasum -a 256 ../../../../web/proto/web.proto | cut -d ' ' -f 1) > protocol.gen.go"
package rpc

