// Server supplies concrete Web handlers. The host owns transport registration.
type Server struct {
	backend   frontend.Backend
	sessions  *backend.SessionService
	usernames map[netip.Addr]string
	cfg       *config.Config
	channels  ChannelAgentChoices
	cronjobs  CronJobs
}

// ChannelAgentChoices supplies the primary connector's current channel policy.
type ChannelAgentChoices interface {
	ChannelAgentChoices(context.Context, string) ([]string, error)
}

// CronJobs uses the process's existing Cron manager for reads and execution.
type CronJobs interface {
	Jobs() ([]cronfrontend.Job, error)
	LoadOneOffCronjob(string) (protocol.OneOffCronjob, error)
	RunOneOffCronjob(context.Context, *protocol.OneOffCronjob) (protocol.CronRunResult, error)
}

// New snapshots WebUsers from the validated startup configuration.
// The host must restrict RPC access to the trusted Web proxy: the metadata
// carries the browser IP, not an independently authenticated network peer.
func New(core frontend.Backend, sessions *backend.SessionService, cfg *config.Config, channels ChannelAgentChoices, cronjobs CronJobs) *Server {
	return &Server{backend: core, sessions: sessions, usernames: maps.Clone(cfg.WebUsers), cfg: cfg, channels: channels, cronjobs: cronjobs}
}

// ListSessionEntries returns ordered entry identifiers and metadata.
func (s *Server) ListSessionEntries(ctx context.Context, request *SessionEntriesRequest) (*ListSessionEntriesResponse, error) {
	entries, err := s.entries(ctx, request.Id)
	if err != nil {
		return nil, err
	}

	response := &ListSessionEntriesResponse{}

	for i := range entries {
		entry := &entries[i]
		response.Entries = append(response.Entries, &SessionEntryMeta{
			Id: entry.ID, Type: entry.Entry.Type, Timestamp: entry.Entry.Timestamp.Format(time.RFC3339Nano),
		})
	}

	return response, nil
}

// LoadSessionEntries returns stored entry values as JSON, preserving int64 IDs.
func (s *Server) LoadSessionEntries(ctx context.Context, request *SessionEntriesRequest) (*LoadSessionEntriesResponse, error) {
	entries, err := s.entries(ctx, request.Id)
	if err != nil {
		return nil, err
	}

	response := &LoadSessionEntriesResponse{}

	for i := range entries {
		entry := &entries[i]

		data, err := json.Marshal(entry.Entry)
		if err != nil {
			return nil, fmt.Errorf("web entries: %w", status.Error(codes.Internal, "encode session entry"))
		}

		response.Entries = append(response.Entries, &SessionEntryData{Id: entry.ID, Json: string(data)})
	}

	return response, nil
}

// DeleteSessionEntries deletes entries only; conversation and goal records remain.
func (s *Server) DeleteSessionEntries(ctx context.Context, request *SessionEntriesRequest) (*DeleteSessionEntriesResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	if strings.TrimSpace(request.Id) == "" {
		return nil, fmt.Errorf("web entries: %w", status.Error(codes.InvalidArgument, "conversation ID is required"))
	}

	deleted, err := s.sessions.DeleteSession(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("web entries: %w", status.Error(codes.Internal, "delete session entries"))
	}

	return &DeleteSessionEntriesResponse{Deleted: deleted}, nil
}

func (s *Server) listSessions(ctx context.Context) (*ListSessionsResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	conversations, err := s.backend.ListConversations(ctx)
	if err != nil {
		return nil, fmt.Errorf("list web conversations: %w", err)
	}

	summaries, err := s.sessions.ListSessions(ctx, backend.SessionListOptions{})
	if err != nil {
		return nil, fmt.Errorf("list web summaries: %w", err)
	}

	response := &ListSessionsResponse{}

	byID := make(map[string]protocol.SessionSummary, len(summaries))
	for _, summary := range summaries {
		byID[summary.ConversationID] = summary
	}

	for _, conversation := range conversations {
		visible, err := s.humanConversation(conversation.ID)
		if err != nil {
			return nil, err
		}

		if !visible {
			continue
		}

		choices, err := s.agentChoices(ctx, conversation.ID)
		if err != nil {
			return nil, err
		}

		session := &Session{Id: conversation.ID, Agent: conversation.Agent, AllowedAgents: choices, Settled: conversation.Settled}
		if summary, exists := byID[conversation.ID]; exists {
			session.Preview = summary.LastUserMessage
			session.UpdatedAt = summary.LastUpdated.Format(time.RFC3339Nano)
		}

		response.Sessions = append(response.Sessions, session)
	}

	slices.SortFunc(response.Sessions, func(a, b *Session) int {
		if order := byID[b.Id].LastUpdated.Compare(byID[a.Id].LastUpdated); order != 0 {
			return order
		}

		return cmp.Compare(a.Id, b.Id)
	})

	return response, nil
}

func (s *Server) history(ctx context.Context, request *HistoryRequest) (*HistoryResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	visible, err := s.humanConversation(request.Id)
	if err != nil {
		return nil, err
	}

	if !visible {
		return nil, fmt.Errorf("web history: %w", status.Error(codes.PermissionDenied, "private conversation"))
	}

	entries, err := s.entries(ctx, request.Id)
	if err != nil {
		return nil, err
	}

	response := &HistoryResponse{}

	for i := range entries {
		entry := &entries[i]

		items, err := rocketcode.ReplayInputToParams(entry.Entry.ReplayInput)
		if err != nil {
			return nil, fmt.Errorf("decode web history: %w", err)
		}

		for i := range items {
			role, text, ok, err := backend.ReplayInputMessageRoleText(&items[i], entry.Entry.ReplayInput[i])
			if err != nil {
				return nil, fmt.Errorf("project web history: %w", err)
			}

			if ok && (role == "user" || role == "assistant") && strings.TrimSpace(text) != "" {
				response.Messages = append(response.Messages, &TranscriptEvent{Role: role, Text: text, Complete: true})
			}
		}
	}

	return response, nil
}

func (s *Server) humanConversation(id string) (bool, error) {
	// These are the private producer locators minted by frontend/cron/manager.go.
	if strings.HasPrefix(id, "cron:") || strings.HasPrefix(id, "one-off-cron:") {
		return false, nil
	}

	_, pair, recorded, err := s.sessions.ExternalMCPSessionByConversationID(id)
	if err != nil {
		return false, fmt.Errorf("resolve web conversation visibility: %w", err)
	}

	return !recorded || pair.PrivateConversationID != id, nil
}

func (s *Server) listCronJobs(ctx context.Context) (*ListCronJobsResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	jobs, err := s.cronjobs.Jobs()
	if err != nil {
		return nil, fmt.Errorf("list web cron jobs: %w", err)
	}

	response := &ListCronJobsResponse{}

	for _, job := range jobs {
		row := &CronJob{Stem: strings.TrimSuffix(strings.TrimPrefix(job.RelativePath, "cron/"), ".md"), Schedule: strings.Join(job.Schedules, ", "), Body: job.Body, Agent: job.Agent, Channel: job.TextChannel, Origin: job.RelativePath}
		for _, at := range job.Upcoming {
			row.Upcoming = append(row.Upcoming, at.Format(time.RFC3339Nano))
		}

		if len(row.Upcoming) > 0 {
			row.NextRun = row.Upcoming[0]
		}

		response.Jobs = append(response.Jobs, row)
	}

	conversations, err := s.backend.ListConversations(ctx)
	if err != nil {
		return nil, fmt.Errorf("list cron history destinations: %w", err)
	}

	var runs []*CronJob

	for _, conversation := range conversations {
		visible, err := s.humanConversation(conversation.ID)
		if err != nil {
			return nil, err
		}

		if !visible {
			continue
		}

		entries, err := s.sessions.ObserveEntries(ctx, conversation.ID, 0)
		if err != nil {
			return nil, fmt.Errorf("read cron history provenance: %w", err)
		}

		runs = append(runs, cronHistory(entries, conversation.ID)...)
	}

	slices.SortFunc(runs, func(a, b *CronJob) int {
		if order := cmp.Compare(b.LastRun, a.LastRun); order != 0 {
			return order
		}

		if order := cmp.Compare(a.NextRun, b.NextRun); order != 0 {
			return order
		}

		return cmp.Compare(a.Origin, b.Origin)
	})
	response.Jobs = append(response.Jobs, runs...)

	return response, nil
}

func cronHistory(entries []backend.ObservedSessionEntry, destination string) []*CronJob {
	var runs []*CronJob

	seen := map[string]bool{}

	for i := range entries {
		source := entries[i].SourceConversationID
		if seen[source] {
			continue
		}
		// Decode the exact locator minted by frontend/cron.cronTraceConversationID.
		path, cron := strings.CutPrefix(source, "cron:")
		if !cron {
			path, cron = strings.CutPrefix(source, "one-off-cron:")
		}

		if !cron {
			continue
		}

		end := strings.LastIndex(path, ":")
		if end < 0 {
			continue
		}

		path = path[:end]

		start := strings.LastIndex(path, ":")
		if start < 0 {
			continue
		}

		at, err := time.Parse("20060102T150405.000000000Z", path[start+1:])
		if err != nil {
			continue
		}

		seen[source] = true
		stem := strings.TrimSuffix(strings.TrimPrefix(path[:start], "cron/"), ".md")
		runs = append(runs, &CronJob{Stem: stem, Status: "ran", LastRun: at.Format("2006-01-02T15:04:05.000000000Z"), NextRun: destination, Origin: source})
	}

	return runs
}

func (s *Server) runCronJob(ctx context.Context, request *RunCronJobRequest) (*RunCronJobResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	job, err := s.cronjobs.LoadOneOffCronjob(request.Stem)
	if err != nil {
		return nil, fmt.Errorf("load web cron job: %w", err)
	}

	result, err := s.cronjobs.RunOneOffCronjob(ctx, &job)
	if err != nil {
		return nil, fmt.Errorf("run web cron job: %w", err)
	}

	return &RunCronJobResponse{Id: result.ConversationID}, nil
}

func (s *Server) settleSession(ctx context.Context, request *SettleSessionRequest) (*SettleSessionResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	visible, err := s.humanConversation(request.Id)
	if err != nil {
		return nil, err
	}

	if !visible {
		return nil, fmt.Errorf("settle web conversation: %w", status.Error(codes.PermissionDenied, "private conversation"))
	}

	updated, err := s.sessions.SetConversationSettled(ctx, request.Id, request.Settled)
	if err != nil {
		return nil, fmt.Errorf("settle web conversation: %w", err)
	}

	if !updated {
		return nil, fmt.Errorf("settle web conversation: %w", status.Error(codes.NotFound, "conversation is not recorded"))
	}

	return &SettleSessionResponse{}, nil
}

func (s *Server) listConfig(ctx context.Context) (*ListConfigResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	// This is the retained UI's allowlist, not serialization of the config.
	view := &ConfigView{
		Workspace: s.cfg.Workspace, Overlays: slices.Clone(s.cfg.Overlays),
		LoggingLevel: s.cfg.Logging.Level, AutoApproverModel: s.cfg.AutoApproverModel,
		InstrumentationEnabled: s.cfg.Instrumentation.Enabled, McpExternal: s.cfg.MCPExternal.Enabled,
		McpServers: slices.Sorted(maps.Keys(s.cfg.MCPServers)),
	}
	for _, name := range slices.Sorted(maps.Keys(s.cfg.Models)) {
		view.Models = append(view.Models, &ConfigModel{Name: name, Model: s.cfg.Models[name]})
	}

	for _, channel := range s.cfg.Slack.Channels {
		view.SlackChannels = append(view.SlackChannels, &ConfigChannel{Channel: channel.Channel, Agents: slices.Clone(channel.Agents)})
	}

	return &ListConfigResponse{Config: view}, nil
}

func (s *Server) listSkills(ctx context.Context) (*ListSkillsResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	_, definitions, err := backend.LoadRuntimeDefinitions(s.cfg, s.cfg.RuntimeDirName())
	if err != nil {
		return nil, fmt.Errorf("load web skills: %w", err)
	}

	response := &ListSkillsResponse{}

	for _, name := range slices.Sorted(maps.Keys(definitions.Items)) {
		skill := definitions.Items[name]
		response.Skills = append(response.Skills, &Skill{Name: name, Description: skill.Description, License: skill.License, Compatibility: skill.Compatibility, Content: skill.Content, Origin: skill.Location})
	}

	return response, nil
}

func (s *Server) listAgents(ctx context.Context) (*ListAgentsResponse, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	definitions, _, err := backend.LoadRuntimeDefinitions(s.cfg, s.cfg.RuntimeDirName())
	if err != nil {
		return nil, fmt.Errorf("load web agents: %w", err)
	}

	response := &ListAgentsResponse{}

	for _, name := range slices.Sorted(maps.Keys(definitions.Items)) {
		agent := definitions.Items[name]
		response.Agents = append(response.Agents, &Agent{Name: name, Model: agent.Model, Reasoning: agent.ReasoningEffort, Description: agent.Description, Verbosity: agent.Verbosity, Prompt: agent.Prompt})
	}

	return response, nil
}

func (s *Server) agentChoices(ctx context.Context, id string) ([]string, error) {
	catalog, err := s.listAgents(ctx)
	if err != nil {
		return nil, err
	}

	choices := make([]string, 0, len(catalog.Agents))
	for _, agent := range catalog.Agents {
		choices = append(choices, agent.Name)
	}

	if channel, _, slack := protocol.SlackThreadTarget(id); slack {
		allowed, err := s.channels.ChannelAgentChoices(ctx, channel)
		if err != nil {
			return nil, fmt.Errorf("web channel choices: %w", err)
		}

		choices = slices.DeleteFunc(choices, func(name string) bool { return !slices.Contains(allowed, name) })
	}

	return choices, nil
}

func (s *Server) createSession(ctx context.Context, request *CreateSessionRequest) (*CreateSessionResponse, error) {
	principal, err := s.principal(ctx)
	if err != nil {
		return nil, err
	}

	choices, err := s.agentChoices(ctx, "")
	if err != nil {
		return nil, err
	}

	if !slices.Contains(choices, request.Agent) {
		return nil, fmt.Errorf("create web conversation: %w", status.Error(codes.InvalidArgument, "select a loaded agent"))
	}

	id := rand.Text()
	if err := s.backend.CreateConversation(ctx, protocol.Conversation{ID: id, Agent: request.Agent, CreatedBy: principal}); err != nil {
		return nil, fmt.Errorf("create web conversation: %w", err)
	}

	return &CreateSessionResponse{Id: id}, nil
}

func (s *Server) prompt(ctx context.Context, request *PromptRequest) (*PromptResponse, error) {
	principal, err := s.principal(ctx)
	if err != nil {
		return nil, err
	}

	if strings.TrimSpace(request.Id) == "" {
		return nil, fmt.Errorf("web prompt: %w", status.Error(codes.InvalidArgument, "conversation ID is required"))
	}

	words := strings.Fields(request.Text)
	if len(words) > 0 && words[0] == "$stop" {
		visible, errVisible := s.humanConversation(request.Id)
		if errVisible != nil {
			return nil, errVisible
		}

		if !visible {
			return nil, fmt.Errorf("web stop: %w", status.Error(codes.PermissionDenied, "private conversation"))
		}

		if len(words) != 1 {
			return nil, fmt.Errorf("web stop: %w", status.Error(codes.InvalidArgument, "stop takes no arguments"))
		}

		inbound := protocol.NewInboundMessage(protocol.SourceWeb, protocol.InboundKindCancel, principal, "", true)
		inbound.ConversationID = request.Id

		inbound.Metadata = map[string]string{protocol.InboundPrincipalMetadataKey: principal}
		if err := s.backend.RunTurn(ctx, inbound); err != nil {
			return nil, fmt.Errorf("web prompt: %w", err)
		}

		return &PromptResponse{}, nil
	}

	if len(words) > 0 && words[0] == "$agent" {
		visible, err := s.humanConversation(request.Id)
		if err != nil {
			return nil, err
		}

		if !visible {
			return nil, fmt.Errorf("web agent: %w", status.Error(codes.PermissionDenied, "private conversation"))
		}

		choices, err := s.agentChoices(ctx, request.Id)
		if err != nil {
			return nil, err
		}

		if len(words) == 1 {
			return &PromptResponse{PrivateText: strings.Join(choices, ", ")}, nil
		}

		if len(words) != 2 || !slices.Contains(choices, words[1]) {
			return nil, fmt.Errorf("web agent: %w", status.Error(codes.InvalidArgument, "agent is not currently allowed"))
		}

		switched, err := s.backend.SwitchConversationAgent(request.Id, words[1])
		if err != nil {
			return nil, fmt.Errorf("switch web agent: %w", err)
		}

		if !switched {
			return nil, fmt.Errorf("web agent: %w", status.Error(codes.NotFound, "conversation is not recorded"))
		}

		return &PromptResponse{PrivateText: "Agent: " + words[1]}, nil
	}

	kind := protocol.InboundKindSteer

	switch request.Delivery {
	case PromptDelivery_STEER:
	case PromptDelivery_QUEUE:
		kind = protocol.InboundKindEnqueue
	default:
		return nil, fmt.Errorf("web prompt: %w", status.Error(codes.InvalidArgument, "unknown prompt delivery"))
	}

	if kind == protocol.InboundKindEnqueue {
		item := &protocol.ThreadQueueItem{
			ID: rand.Text(), Message: request.Text, Principal: principal, Source: protocol.SourceWeb,
			Kind: protocol.InboundKindEnqueue, Content: protocol.InboundContent{Text: request.Text}, StashAt: time.Now().UTC(),
		}
		if err := s.backend.StashQueueItem(ctx, request.Id, item); err != nil {
			return nil, fmt.Errorf("web prompt: %w", err)
		}

		return &PromptResponse{}, nil
	}

	inbound := protocol.NewInboundMessage(protocol.SourceWeb, kind, principal, request.Text, true)
	inbound.ConversationID = request.Id

	inbound.Metadata = map[string]string{protocol.InboundPrincipalMetadataKey: principal}
	if err := s.backend.RunTurn(ctx, inbound); err != nil {
		return nil, fmt.Errorf("web prompt: %w", err)
	}

	return &PromptResponse{}, nil
}

func (s *Server) listQueue(ctx context.Context, request *ListQueueRequest) (*ListQueueResponse, error) {
	if err := s.visibleConversation(ctx, request.Id); err != nil {
		return nil, err
	}

	items, err := s.backend.QueueItems(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("list web queue: %w", err)
	}

	response := &ListQueueResponse{}
	for i := range items {
		response.Items = append(response.Items, &QueueItem{Id: items[i].ID, Text: items[i].Message})
	}

	return response, nil
}

func (s *Server) steerQueueItem(ctx context.Context, request *QueueItemRequest) (*QueueItemResponse, error) {
	if err := s.visibleConversation(ctx, request.Id); err != nil {
		return nil, err
	}

	if strings.TrimSpace(request.ItemId) == "" {
		return nil, fmt.Errorf("web queue: %w", status.Error(codes.InvalidArgument, "queue item ID is required"))
	}

	promoted, err := s.backend.PromoteQueueItem(ctx, request.Id, request.ItemId)
	if err != nil {
		return nil, fmt.Errorf("promote web queue item: %w", err)
	}

	if !promoted {
		return nil, fmt.Errorf("web queue: %w", status.Error(codes.NotFound, "queue item is not recorded"))
	}

	return &QueueItemResponse{}, nil
}

func (s *Server) removeQueueItem(ctx context.Context, request *QueueItemRequest) (*QueueItemResponse, error) {
	if err := s.visibleConversation(ctx, request.Id); err != nil {
		return nil, err
	}

	if strings.TrimSpace(request.ItemId) == "" {
		return nil, fmt.Errorf("web queue: %w", status.Error(codes.InvalidArgument, "queue item ID is required"))
	}

	removed, err := s.backend.DeleteQueueItem(ctx, request.Id, request.ItemId)
	if err != nil {
		return nil, fmt.Errorf("remove web queue item: %w", err)
	}

	if !removed {
		return nil, fmt.Errorf("web queue: %w", status.Error(codes.NotFound, "queue item is not recorded"))
	}

	return &QueueItemResponse{}, nil
}

func (s *Server) reorderQueue(ctx context.Context, request *ReorderQueueRequest) (*QueueItemResponse, error) {
	if err := s.visibleConversation(ctx, request.Id); err != nil {
		return nil, err
	}

	if err := s.backend.ReorderQueueItems(ctx, request.Id, request.ItemIds); err != nil {
		return nil, fmt.Errorf("reorder web queue: %w", err)
	}

	return &QueueItemResponse{}, nil
}

func (s *Server) visibleConversation(ctx context.Context, id string) error {
	if _, err := s.principal(ctx); err != nil {
		return err
	}

	if strings.TrimSpace(id) == "" {
		return fmt.Errorf("web queue: %w", status.Error(codes.InvalidArgument, "conversation ID is required"))
	}

	visible, err := s.humanConversation(id)
	if err != nil {
		return err
	}

	if !visible {
		return fmt.Errorf("web queue: %w", status.Error(codes.PermissionDenied, "private conversation"))
	}

	return nil
}

func (s *Server) join(request *JoinRequest, stream grpc.ServerStream) error {
	if _, err := s.principal(stream.Context()); err != nil {
		return err
	}

	if strings.TrimSpace(request.Id) == "" {
		return fmt.Errorf("web join: %w", status.Error(codes.InvalidArgument, "conversation ID is required"))
	}

	for event := range s.backend.Subscribe(stream.Context()) {
		message := event.Message

		var err error

		if message.ConversationID == request.Id {
			if message.ProgressText != "" {
				err = stream.SendMsg(&TranscriptEvent{Text: message.ProgressText, Role: "thinking", TurnId: message.TurnID})
			}

			if err == nil && (message.Text != "" || message.Complete) {
				err = stream.SendMsg(&TranscriptEvent{Text: message.Text, Role: "assistant", Complete: message.Complete, TurnId: message.TurnID})
			}
		}

		event.Acknowledgement <- err

		if err != nil {
			return fmt.Errorf("web live event: %w", err)
		}
	}

	return nil
}

func (s *Server) principal(ctx context.Context) (string, error) {
	values := metadata.ValueFromIncomingContext(ctx, "rocketclaw-principal")
	if len(values) != 1 {
		return "", fmt.Errorf("web principal: %w", status.Error(codes.Unauthenticated, "browser IP is required"))
	}

	ip, err := netip.ParseAddr(values[0])
	if err != nil {
		return "", fmt.Errorf("web principal: %w", status.Error(codes.Unauthenticated, "invalid browser IP"))
	}

	username := s.usernames[ip]
	if username == "" {
		return "", fmt.Errorf("web principal: %w", status.Error(codes.Unauthenticated, "browser IP is not configured"))
	}

	return username, nil
}

func (s *Server) entries(ctx context.Context, id string) ([]backend.ObservedSessionEntry, error) {
	if _, err := s.principal(ctx); err != nil {
		return nil, err
	}

	if strings.TrimSpace(id) == "" {
		return nil, fmt.Errorf("web entries: %w", status.Error(codes.InvalidArgument, "conversation ID is required"))
	}

	entries, err := s.sessions.ObserveEntries(ctx, id, 0)
	if err != nil {
		return nil, fmt.Errorf("web entries: %w", status.Error(codes.Internal, "load session entries"))
	}

	return entries, nil
}
